"use strict";

// OneSend wrapper around the unmodified libcimbar WASM release. The wrapper
// keeps camera pixels, recovery, validation, and decompression inside a
// dedicated worker; it never uploads file or camera data.

var Module = {
  preRun: [],
  onRuntimeInitialized: function () {
    Module._cimbard_configure_decode(68); // mode B
    fountainBufferSize = Module._cimbard_get_bufsize();
    allocate("fountain", fountainBufferSize);
    initialized = true;
    postMessage({
      type: "ready",
      mode: "B",
      bufferSize: fountainBufferSize,
    });
  },
};

const allocations = new Map();
let fountainBufferSize = 0;
let initialized = false;
let completed = false;

function allocate(name, size) {
  const previous = allocations.get(name);
  if (previous && previous.size >= size) {
    return new Uint8Array(Module.HEAPU8.buffer, previous.pointer, previous.size);
  }

  if (previous) Module._free(previous.pointer);
  const allocation = {
    pointer: Module._malloc(size),
    size,
  };
  allocations.set(name, allocation);
  return new Uint8Array(Module.HEAPU8.buffer, allocation.pointer, allocation.size);
}

function allocationView(name) {
  const allocation = allocations.get(name);
  if (!allocation) throw new Error(`Missing WASM allocation: ${name}`);
  return new Uint8Array(Module.HEAPU8.buffer, allocation.pointer, allocation.size);
}

function readReport() {
  const buffer = allocate("report", 4096);
  const length = Module._cimbard_get_report(buffer.byteOffset, buffer.length);
  if (length <= 0) return null;

  const text = new TextDecoder().decode(buffer.subarray(0, length));
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

function progressFromReport(report) {
  if (!Array.isArray(report) || report.length === 0) return null;
  const progress = Math.max(...report.map((value) => Number(value)));
  return Number.isFinite(progress) ? Math.max(0, Math.min(1, progress)) : null;
}

function isComplete(value) {
  return typeof value === "bigint" ? value > 0n : value > 0;
}

function numericId(value) {
  return typeof value === "bigint" ? Number(value & 0xffffffffn) : Number(value);
}

function decompressFile(id) {
  const bufferSize = Module._cimbard_get_decompress_bufsize();
  const buffer = allocate("decompress", bufferSize);
  const chunks = [];
  let total = 0;
  const maxOutput = self.OneSendCimbarEnvelope.MAX_ENVELOPE_BYTES;

  while (true) {
    const read = Module._cimbard_decompress_read(
      id,
      buffer.byteOffset,
      buffer.length,
    );
    if (read < 0) throw new Error(`libcimbar 解压失败（${read}）`);
    if (read === 0) break;

    total += read;
    if (total > maxOutput) {
      throw new Error("文件超过 33 MiB 浏览器实验上限。");
    }
    chunks.push(new Uint8Array(Module.HEAPU8.buffer, buffer.byteOffset, read).slice());
  }

  const bytes = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.length;
  }
  return bytes;
}

function sourcePixels(data) {
  if (data.pixels instanceof ArrayBuffer) return new Uint8Array(data.pixels);
  return new Uint8Array(data.pixels.buffer, data.pixels.byteOffset, data.pixels.byteLength);
}

function processFrame(data) {
  if (!initialized || completed) return;

  const pixels = sourcePixels(data);
  const image = allocate("image", pixels.byteLength);
  image.set(pixels);

  const bytes = Module._cimbard_scan_extract_decode(
    image.byteOffset,
    data.width,
    data.height,
    data.format === "NV12" ? 12 : data.format === "I420" ? 420 : 4,
    allocationView("fountain").byteOffset,
    fountainBufferSize,
  );

  if (bytes <= 0) {
    postMessage({ type: "frame", result: "no-data", frameDone: true });
    return;
  }

  const result = Module._cimbard_fountain_decode(
    allocationView("fountain").byteOffset,
    bytes,
  );
  const report = readReport();
  const progress = progressFromReport(report);

  if (!isComplete(result)) {
    postMessage({
      type: "frame",
      result: "decoded",
      progress,
      frameDone: true,
    });
    return;
  }

  const id = numericId(result);
  const envelopeBytes = decompressFile(id);
  const decoded = self.OneSendCimbarEnvelope.decode(envelopeBytes);
  if (decoded.verified !== true) {
    throw new Error("CIMBAR envelope 未通过 CRC32 校验。");
  }
  const fileBytes = decoded.bytes;
  completed = true;
  postMessage(
    {
      type: "complete",
      name: decoded.name,
      mimeType: decoded.mimeType,
      bytes: fileBytes.buffer,
      crc32: decoded.crc32,
      verified: true,
      progress: 1,
    },
    [fileBytes.buffer],
  );
}

importScripts(
  "/cimbar/onesend_cimbar_envelope.js",
  "cimbar_js.2026-07-13T0523.js",
);

self.onmessage = (event) => {
  const data = event.data || {};
  if (data.type !== "frame") return;

  try {
    processFrame(data);
  } catch (error) {
    postMessage({
      type: "error",
      frameDone: true,
      message: error instanceof Error ? error.message : String(error),
    });
  }
};
